    tok = token.strip()
    if not tok:
        return None
    # Normalize OCR confusions
    tok = tok.replace('O', '0').replace('o', '0')
    tok = re.sub(r'\s*([.,])\s*', r'\1', tok)

    # If token has spaces but no separators, assume last group is cents
    if ' ' in tok and '.' not in tok and ',' not in tok:
        parts = tok.split()
        if len(parts) >= 2 and len(parts[-1]) == 2:
            tok = ''.join(parts[:-1]) + '.' + parts[-1]
        else:
            tok = ''.join(parts)

    # Convert comma decimal or thousands
    if ',' in tok and '.' not in tok:
        if re.search(r',\d{2}$', tok):
            tok = tok.replace(',', '.')
        else:
            tok = tok.replace(',', '')
    elif ',' in tok and '.' in tok:
        # Keep last separator as decimal
        if tok.rfind(',') > tok.rfind('.'):
            tok = tok.replace('.', '')
            tok = tok.replace(',', '.')
        else:
            tok = tok.replace(',', '')

    # If multiple dots, keep last as decimal
    if tok.count('.') > 1:
        last = tok.rfind('.')
        tok = tok[:last].replace('.', '') + tok[last:]

    if re.fullmatch(r'\d+(?:\.\d{1,2})?', tok):
        return tok
    return None


def find_amount_candidates(line: str):
    # Replace spaces around decimal points/commas between digits
    line = line.replace('O', '0').replace('o', '0')
    line = re.sub(r'(\d)\s*([.,])\s*(\d)', r'\1\2\3', line)
    # Try to capture numeric-like tokens
    tokens = []
    for m in re.finditer(r'\d[\d,\.\s]*\d', line):
        tok = m.group(0)
        norm = normalize_token(tok)
        if norm:
            tokens.append(norm)
    return tokens


