    try:
        val = Decimal(num_str)
    except InvalidOperation:
        return None
    return f"{val:.2f}"


def extract_total(lines):
    upper_lines = [ln.upper() for ln in lines]
    # Precompute all decimal candidates for heuristic scaling
    all_candidates = []
    for ln in lines:
        for tok in find_amount_candidates(ln):
            if '.' in tok:
                all_candidates.append(Decimal(tok))
    for group in KEY_GROUPS:
        for i, u in enumerate(upper_lines):
            if any(ex in u for ex in EXCLUDE):
                continue
            if any(k in u for k in group):
                line = lines[i]
                nums = find_amount_candidates(line)
                if nums:
                    # choose last numeric token on the line
                    chosen = nums[-1]
                    # Heuristic: if no decimal and looks like cents merged (e.g., 1000 for 10.00)
                    if '.' not in chosen and len(chosen) >= 4:
                        try:
                            as_int = int(chosen)
                            for cand in all_candidates:
