    m = re.search(r'\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})\b', text)
    if not m:
        return None
    a, b, y = m.groups()
    ai, bi = int(a), int(b)
    if ai > 12 and bi <= 12:
        return parse_date(y, b, a)
    if bi > 12 and ai <= 12:
        return parse_date(y, a, b)
    # ambiguous: prefer day-first
    iso = parse_date(y, b, a)
    return iso or parse_date(y, a, b)


def parse_dmy2_match(text):
    m = re.search(r'\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{2})\b', text)
    if not m:
        return None
    a, b, y2 = m.groups()
    ai, bi = int(a), int(b)
    y = int(y2)
    y_full = 2000 + y if y < 70 else 1900 + y
    if ai > 12 and bi <= 12:
        return parse_date(str(y_full), b, a)
    if bi > 12 and ai <= 12:
        return parse_date(str(y_full), a, b)
    iso = parse_date(str(y_full), b, a)
    return iso or parse_date(str(y_full), a, b)


def extract_date(lines):
    # Prefer lines containing "DATE"
    ordered_lines = []
    for ln in lines:
        if any(h in ln.upper() for h in DATE_LINE_HINTS):
            ordered_lines.append(ln)
    ordered_lines += [ln for ln in lines if ln not in ordered_lines]

    for ln in ordered_lines:
        for fn in (parse_ymd_match, parse_dmy_match, parse_dmy2_match):
            iso = fn(ln)
            if iso:
                return iso

    # Fallback: scan full text
    text = '\n'.join(lines)
    for fn in (parse_ymd_match, parse_dmy_match, parse_dmy2_match):
        iso = fn(text)
        if iso:
            return iso

    # Fallback: 8-digit date in invoice-like lines
    for ln in lines:
        u = ln.upper()
        if any(h in u for h in INVOICE_HINTS):
            m = re.search(r'\b(20\d{2})(\d{2})(\d{2})\b', ln)
            if m:
                y, mth, d = m.groups()
                iso = parse_date(y, mth, d)
                if iso:
                    return iso
    return None


rows = []
files = sorted([f for f in os.listdir(IMG_DIR) if os.path.isfile(os.path.join(IMG_DIR, f))])

for fname in files:
    path = os.path.join(IMG_DIR, fname)
    try:
        text = ocr_text(path)
    except Exception:
        rows.append({'filename': fname, 'date': None, 'total_amount': None})
        continue
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    date_val = extract_date(lines)
    total_val = extract_total(lines)
    rows.append({'filename': fname, 'date': date_val, 'total_amount': total_val})

# Write Excel
