EXCLUDE = [
    'SUBTOTAL', 'SUB TOTAL', 'TAX', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED',
    'EXCLUDING', 'EXCL', 'EXCLUSIVE'
]

KEY_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM', 'TOTAL:', 'TOTAL AMOUNT', 'TOTAL SALES'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'],
    ['TOTAL'],
    ['AMOUNT'],
]

TOTAL_HINTS = ['TOTAL', 'GRAND', 'DUE', 'BALANCE', 'NET']
GST_ALLOW_HINTS = ['INCL', 'INCLUDE', 'INCLUDING', 'INCLUSIVE']
HEADER_HINTS = ['QTY', 'ITEM', 'DESC', 'DESCRIPTION', 'PRICE', 'U/PRICE', 'U.PRICE', 'U PRICE', 'RM CODE', 'CODE']
DATE_LINE_HINTS = ['DATE', 'DTE']
INVOICE_HINTS = ['INVOICE', 'INV', 'RECEIPT']


def ocr_text(path: str) -> str:
    img = Image.open(path)
    img = ImageOps.grayscale(img)
    img = ImageOps.autocontrast(img)
    return pytesseract.image_to_string(img, config='--psm 6')


def normalize_token(token: str) -> str | None:
    tok = token.strip()
    if not tok:
        return None
    tok = tok.replace('O', '0').replace('o', '0')
    tok = re.sub(r'\s*([.,])\s*', r'\1', tok)
    if ' ' in tok and '.' not in tok and ',' not in tok:
        parts = tok.split()
        if len(parts) >= 2 and len(parts[-1]) == 2:
            tok = ''.join(parts[:-1]) + '.' + parts[-1]
        else:
            tok = ''.join(parts)

    if ',' in tok and '.' not in tok:
        if re.search(r',\d{2}$', tok):
            tok = tok.replace(',', '.')
        else:
            tok = tok.replace(',', '')
    elif ',' in tok and '.' in tok:
        if tok.rfind(',') > tok.rfind('.'):
            tok = tok.replace('.', '')
            tok = tok.replace(',', '.')
        else:
            tok = tok.replace(',', '')

    if tok.count('.') > 1:
        last = tok.rfind('.')
        tok = tok[:last].replace('.', '') + tok[last:]

    if re.fullmatch(r'\d+(?:\.\d{1,2})?', tok):
        return tok
    return None


def find_amount_candidates(line: str):
    line = line.replace('O', '0').replace('o', '0')
    line = re.sub(r'(\d)\s*([.,])\s*(\d)', r'\1\2\3', line)
    tokens = []
    for m in re.finditer(r'\d[\d,\.\s]*\d', line):
        tok = m.group(0)
        norm = normalize_token(tok)
        if norm:
            tokens.append(norm)
    return tokens


def format_amount(num_str: str):
    try:
        val = Decimal(num_str)
    except InvalidOperation:
        return None
    return f"{val:.2f}"


def is_header_line(u: str) -> bool:
    if any(h in u for h in HEADER_HINTS):
        if not any(t in u for t in TOTAL_HINTS):
            return True
    return False


def is_excluded_line(u: str) -> bool:
    if any(ex in u for ex in EXCLUDE):
        return True
    if 'GST' in u:
        if not any(h in u for h in GST_ALLOW_HINTS):
            return True
    return False


