                if 'TOTAL' in u and ('ITEM' in u or 'QTY' in u) and 'RM' not in u:
                    continue
                nums = find_amount_candidates(lines[i])
                if nums:
                    chosen = nums[-1]
                    if '.' not in chosen and len(chosen) >= 4:
                        try:
                            as_int = int(chosen)
                            for cand in all_candidates:
                                if int(cand * 100) == as_int:
                                    chosen = f"{cand}"
                                    break
                        except Exception:
                            pass
                    return format_amount(chosen)
                # fallback to next non-empty line if this line looks like a total label
                for j in range(i + 1, len(lines)):
                    if lines[j].strip():
                        nums2 = find_amount_candidates(lines[j])
                        if nums2:
                            return format_amount(nums2[-1])
                        break
    return None


def parse_date(y, m, d):
    try:
        return datetime(int(y), int(m), int(d)).date().isoformat()
    except ValueError:
        return None


def parse_ymd(text):
    m = re.search(r'\b(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})\b', text)
    if not m:
        return None
    y, mth, d = m.groups()
    return parse_date(y, mth, d)


def parse_dmy(text):
    m = re.search(r'\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})\b', text)
    if not m:
        return None
    a, b, y = m.groups()
    ai, bi = int(a), int(b)
    if ai > 12 and bi <= 12:
        return parse_date(y, b, a)
    if bi > 12 and ai <= 12:
        return parse_date(y, a, b)
    iso = parse_date(y, b, a)
    return iso or parse_date(y, a, b)


def parse_dmy2(text):
    m = re.search(r'\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{2})\b', text)
    if not m:
        return None
    a, b, y2 = m.groups()
    ai, bi = int(a), int(b)
    y = int(y2)
    y_full = 2000 + y if y < 70 else 1900 + y
    if ai > 12 and bi <= 12:
        return parse_date(str(y_full), b, a)
    if bi > 12 and ai <= 12:
        return parse_date(str(y_full), a, b)
    iso = parse_date(str(y_full), b, a)
    return iso or parse_date(str(y_full), a, b)


def extract_date(lines):
    ordered_lines = []
    for ln in lines:
        if any(h in ln.upper() for h in DATE_LINE_HINTS):
            ordered_lines.append(ln)
    ordered_lines += [ln for ln in lines if ln not in ordered_lines]

    for ln in ordered_lines:
        for fn in (parse_ymd, parse_dmy, parse_dmy2):
            iso = fn(ln)
            if iso:
                return iso

    text = '\n'.join(lines)
    for fn in (parse_ymd, parse_dmy, parse_dmy2):
        iso = fn(text)
        if iso:
            return iso

    for ln in lines:
        u = ln.upper()
        if any(h in u for h in INVOICE_HINTS):
            m = re.search(r'(20\d{2})(\d{2})(\d{2})', ln)
            if m:
                y, mth, d = m.groups()
                iso = parse_date(y, mth, d)
                if iso:
                    return iso
    return None


